  const [draft, setDraft] = React.useState(cfg);
  React.useEffect(() => { setDraft(cfg); }, []);
  const upd = (patch) => setDraft(d => ({ ...d, ...patch }));
  const save = () => {
    setSLAConfig(draft);
    window.toast('บันทึก SLA แล้ว — มีผลกับคำขอใหม่และคำขอที่ยังอยู่ในกระบวนการ', { level: 'success' });
  };
  const reset = () => { setDraft(DEFAULT_SLA); window.toast('รีเซ็ตเป็นค่าเริ่มต้น (ยังไม่บันทึก)', { level: 'info' }); };
