// ===== v3.1: จัดการรายการตัวเลือก (dropdown ในฟอร์มต่างๆ) =====
const OptionListsSettings = ({ ctx }) => {
  const { state, setState } = ctx;
  const [newVals, setNewVals] = React.useState({});
  const setList = (key, items) => setState({ optionLists: { ...(state.optionLists || {}), [key]: { items, updatedAt: Date.now() } } });
  const add = (key) => {
    const v = (newVals[key] || '').trim();
    const cur = getOptionItems(state, key);
    if (!v) return;
    if (cur.includes(v)) { window.toast('มีตัวเลือกนี้อยู่แล้ว', { level: 'warning' }); return; }
    setList(key, [...cur, v]);
    setNewVals({ ...newVals, [key]: '' });
    window.toast(`เพิ่ม "${v}" แล้ว`, { level: 'success' });
  };
  const del = (key, item) => {
    if (!confirm(`ลบ "${item}" ออกจากรายการ?\n(คำขอเดิมที่ใช้ค่านี้ไม่ได้รับผลกระทบ — ยังแสดงค่าเดิมได้)`)) return;
    setList(key, getOptionItems(state, key).filter(x => x !== item));
  };
  const rename = (key, item) => {
    const v = (prompt(`แก้ไขตัวเลือก`, item) || '').trim();
    if (!v || v === item) return;
    const cur = getOptionItems(state, key);
    if (cur.includes(v)) { window.toast('มีตัวเลือกนี้อยู่แล้ว', { level: 'warning' }); return; }
    setList(key, cur.map(x => x === item ? v : x));
  };
  return (
    <div className="col gap-16">
      <div className="alert alert-info">
        <Icon name="info" size={14} style={{ marginTop: 1 }} />
        <div className="text-xs flex-1">รายการตัวเลือกของช่อง dropdown ในฟอร์มต่างๆ — เพิ่มได้ทั้งจากที่นี่ และจากปุ่ม "➕ เพิ่มตัวเลือกใหม่" ในตัว dropdown ตอนกรอกฟอร์ม · ข้อมูล sync ข้ามเครื่องอัตโนมัติ · การลบไม่กระทบคำขอเดิมที่ใช้ค่านั้นไปแล้ว</div>
      </div>
      <div className="grid grid-2" style={{ gap: 16, alignItems: 'start' }}>
        {Object.keys(OPTION_LIST_META).map(key => {
          const meta = OPTION_LIST_META[key];
          const items = getOptionItems(state, key);
          return (
            <div key={key} className="card card-pad">
              <div className="row gap-10 mb-4">
                <div style={{ width: 34, height: 34, borderRadius: 8, background: 'var(--brand-soft)', display: 'grid', placeItems: 'center', color: 'var(--brand-ink)' }}><Icon name={meta.icon} size={16} /></div>
                <div className="flex-1">
                  <div className="medium text-sm">{meta.th}</div>
                  <div className="text-xs muted">{meta.desc} · {items.length} ตัวเลือก</div>
                </div>
              </div>
              <div className="row gap-6 flex-wrap mt-8 mb-10">
                {items.length === 0 && <span className="text-xs muted">ยังไม่มีตัวเลือก — เพิ่มด้านล่าง</span>}
                {items.map(item => (
                  <span key={item} className="chip" style={{ cursor: 'default', display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                    <span onClick={() => rename(key, item)} style={{ cursor: 'pointer' }} title="คลิกเพื่อแก้ไข">{item}</span>
                    <span onClick={() => del(key, item)} style={{ cursor: 'pointer', color: 'var(--red-ink)', display: 'inline-flex' }} title="ลบ"><Icon name="x" size={10} /></span>
                  </span>
                ))}
              </div>
              <div className="row gap-6">
                <input className="input" style={{ height: 34, flex: 1 }} value={newVals[key] || ''}
                  onChange={(e) => setNewVals({ ...newVals, [key]: e.target.value })}
                  onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); add(key); } }}
                  placeholder="พิมพ์ตัวเลือกใหม่..." />
                <button className="btn btn-primary btn-sm" style={{ height: 34 }} onClick={() => add(key)}><Icon name="plus" size={12} /> เพิ่ม</button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

